window.kbPageData["views/practice/s-300f89e88263b685"] = {"key":"practice/s-300f89e88263b685","state":{"route":"practice/s-300f89e88263b685"},"tree":"<a data-toc-link href=\"#skills/xingce\">行测技能首页</a><details data-branch=\"module-政治理论\"><summary>政治理论</summary><div class=\"tocChildren\"><a data-toc-link href=\"#skills/xingce/%E6%94%BF%E6%B2%BB%E7%90%86%E8%AE%BA\">专题概览</a><a data-toc-link href=\"#practice/theory\">理论原理与材料对应</a><a data-toc-link href=\"#practice/policy\">政策目标与具体举措</a><a data-toc-link href=\"#practice/institutions\">制度、文件与规范表述</a></div></details><details data-branch=\"wording\"><summary>时政措辞辨析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/wording\">专题概览</a><a data-toc-link href=\"#practice/wording/conditions\">必须、可以与例外条件</a><a data-toc-link href=\"#practice/wording/degree\">强度、进度与结果</a><a data-toc-link href=\"#practice/wording/roles\">首要任务、根本保证与具体分工</a><a data-toc-link href=\"#practice/wording/scope\">主体、对象与适用范围</a><a data-toc-link href=\"#practice/wording/authority\">宪法、党章与制度权限</a><a data-toc-link href=\"#practice/wording/direction\">方向、分类与历史阶段</a></div></details><details data-branch=\"module-常识判断\"><summary>常识判断</summary><div class=\"tocChildren\"><a data-toc-link href=\"#skills/xingce/%E5%B8%B8%E8%AF%86%E5%88%A4%E6%96%AD\">专题概览</a><a data-toc-link href=\"#practice/law\">法律规则与案例</a><a data-toc-link href=\"#practice/science\">科技、地理与生活现象</a><a data-toc-link href=\"#practice/public-affairs\">经济、政策与公共管理</a><a data-toc-link href=\"#practice/history-culture\">历史人文与国情</a></div></details><details data-branch=\"module-言语理解与表达\" open><summary>言语理解与表达</summary><div class=\"tocChildren\"><a data-toc-link href=\"#skills/xingce/%E8%A8%80%E8%AF%AD%E7%90%86%E8%A7%A3%E4%B8%8E%E8%A1%A8%E8%BE%BE\">专题概览</a><a data-toc-link href=\"#practice/s-bc177199c1351631\">根据语境辨析词语</a><a data-toc-link href=\"#practice/s-gist\">主旨与作者意图</a><a data-toc-link href=\"#practice/s-c5eac332ba86912d\">结合搭配对象辨析用词</a><a data-toc-link href=\"#practice/s-ef0f414c890a2427\">核对原文与选项</a><a data-toc-link href=\"#practice/s-4eebda7bdff18647\">补全语句衔接</a><a data-toc-link href=\"#practice/s-871196fcda246b8d\">语句排序与插入</a><a data-toc-link href=\"#practice/s-94e5b1e84b4945ab\">推断下文</a><a data-toc-link href=\"#practice/s-0a0bc5508fefda64\">拟定文段标题</a><a data-toc-link href=\"#practice/s-8713d7d1007a8167\">词句含义与指代</a><a data-toc-link href=\"#practice/s-84ff0f0fbbe378d8\">结合语境辨析成语</a><a data-toc-link href=\"#practice/s-b2f959b1b4484115\">辨认材料支持的观点</a><a data-toc-link href=\"#practice/s-300f89e88263b685\" aria-current=\"page\">通过转折定位文段重心</a><a data-toc-link href=\"#practice/s-4159fb5ba3bc2963\">运用文段给出的标准判断实例</a></div></details><details data-branch=\"module-数量关系\"><summary>数量关系</summary><div class=\"tocChildren\"><a data-toc-link href=\"#skills/xingce/%E6%95%B0%E9%87%8F%E5%85%B3%E7%B3%BB\">专题概览</a><a data-toc-link href=\"#practice/s-ac5c371e800baa75\">几何构造与度量</a><a data-toc-link href=\"#practice/s-d968fce424f6218d\">等量关系列方程</a><a data-toc-link href=\"#practice/s-c0f6c7e3ae9d902e\">排列组合与分类计数</a><a data-toc-link href=\"#practice/s-bfe8437fe159274c\">拆分与改写数列</a><a data-toc-link href=\"#practice/s-4d945e4b584e20e6\">工程量与效率</a><a data-toc-link href=\"#practice/s-a678755b344c536e\">行程、相遇与追及</a><a data-toc-link href=\"#practice/s-fa618aa0e5554dde\">事件概率与几何概率</a><a data-toc-link href=\"#practice/s-36722f3b0a111400\">周期与余数</a><a data-toc-link href=\"#practice/s-36bcdccc44445c07\">用容斥计算重叠人数</a><a data-toc-link href=\"#practice/s-27070cd6f8f1808e\">约束条件下求最值</a><a data-toc-link href=\"#practice/s-55b69f4a0862f7f1\">成本、售价与收入</a><a data-toc-link href=\"#practice/s-98ca154ecf4968d7\">利用整数条件求解不定方程</a><a data-toc-link href=\"#practice/s-7ee6e0e28c7c40e3\">辨认数列递推或周期规律</a><a data-toc-link href=\"#practice/s-261f4b85ee542fe2\">代入选项验算</a><a data-toc-link href=\"#practice/s-4c82ef55d2b649c7\">数列作差与作商</a><a data-toc-link href=\"#practice/s-5864586ebd669b08\">等差数列求项与求和</a><a data-toc-link href=\"#practice/s-7c91e017f98bac24\">用比例赋值简化计算</a><a data-toc-link href=\"#practice/s-f6792163b580976b\">按溶质量守恒计算混合与稀释</a><a data-toc-link href=\"#practice/s-b0dec29a0ef842cb\">按边权选择最小生成树的边</a><a data-toc-link href=\"#practice/s-ff03c13adcbe7233\">端点与间隔计数</a></div></details><details data-branch=\"module-判断推理\"><summary>判断推理</summary><div class=\"tocChildren\"><a data-toc-link href=\"#skills/xingce/%E5%88%A4%E6%96%AD%E6%8E%A8%E7%90%86\">专题概览</a><a data-toc-link href=\"#practice/s-conditions\">按题内定义核对案例条件</a><a data-toc-link href=\"#practice/s-d45531f0ca63ae30\">类比关系与词项顺序</a><a data-toc-link href=\"#practice/s-aa16640dd943508a\">多条件对应与排序</a><a data-toc-link href=\"#practice/s-c96dc3b8ef59659c\">图形元素计数</a><a data-toc-link href=\"#practice/s-tiles\">按边界重组平面碎片</a><a data-toc-link href=\"#practice/s-2ee7513507dfe397\">用证据加强结论</a><a data-toc-link href=\"#practice/s-afb05982fcc9a31c\">判断展开图的邻面、图案和公共边</a><a data-toc-link href=\"#practice/s-449334f5aeb5ea84\">图形平移、旋转与翻折</a><a data-toc-link href=\"#practice/s-b675a81beafb818e\">立体视图与截面</a><a data-toc-link href=\"#practice/s-449c824eeb0b7f3d\">对称与形状属性</a><a data-toc-link href=\"#practice/s-bd23484a6c3aa41a\">检验论证成立的条件</a><a data-toc-link href=\"#practice/s-8e029448a5228c68\">条件推理与结论范围</a><a data-toc-link href=\"#practice/s-26718cf11a50ed78\">构词与词义关系</a><a data-toc-link href=\"#practice/s-cd83588b8b1f05cb\">事件关系与语序</a><a data-toc-link href=\"#practice/s-ae670e69128d8e55\">削弱因果推断</a><a data-toc-link href=\"#practice/s-73b5da0d39715bb4\">辨认图形接触、相交和公共边</a><a data-toc-link href=\"#practice/s-e207f62725dca283\">梳理论证链</a><a data-toc-link href=\"#practice/s-ca43cd3fbda05045\">比对概念的外延和分类关系</a><a data-toc-link href=\"#practice/s-9f74c42e488abf6f\">比较论证结构</a><a data-toc-link href=\"#practice/s-49e530b3a2c0cd4c\">叠加与黑白变化</a><a data-toc-link href=\"#practice/s-599d7fb5a061494c\">图形连通与分离</a><a data-toc-link href=\"#practice/s-182392c898d56a84\">对象的属性、构成与用途</a><a data-toc-link href=\"#practice/s-f3b05c49f6712148\">根据真假数量确定陈述真值</a><a data-toc-link href=\"#practice/s-4e6dc1eac45ccce0\">检验样本是否支持总体推断</a><a data-toc-link href=\"#practice/s-9f1e8d490dc6971d\">判断证据能否削弱结论</a><a data-toc-link href=\"#practice/s-2a7fe675bd0d6265\">图形位置与方向</a><a data-toc-link href=\"#practice/s-ba9cd0f2f572724c\">按指标定义计算比值</a><a data-toc-link href=\"#practice/s-1e26b8e07773b68a\">数量约束与枚举</a><a data-toc-link href=\"#practice/s-db4885a9ca6b54c2\">按规则比较与排序</a><a data-toc-link href=\"#practice/s-fbc7bd8e0e436bca\">按图示规则追踪关系</a><a data-toc-link href=\"#practice/s-33e33ba24dd315ec\">解释现象与差异</a><a data-toc-link href=\"#practice/s-15c5a161061d35d8\">比较图形涂色面积的变化</a></div></details><details data-branch=\"module-资料分析\"><summary>资料分析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#skills/xingce/%E8%B5%84%E6%96%99%E5%88%86%E6%9E%90\">专题概览</a><a data-toc-link href=\"#practice/s-e9ffdd08e7f0ec51\">平均数、比值与倍数</a><a data-toc-link href=\"#practice/s-f29bc501c32a5bee\">增长量与平均增量</a><a data-toc-link href=\"#practice/s-a7ce466b25f8ea1b\">比重、部分与总体</a><a data-toc-link href=\"#practice/s-22e0d443f4e8833e\">比较比重与百分点差</a><a data-toc-link href=\"#practice/s-rates\">同比、环比与基准期</a><a data-toc-link href=\"#practice/s-base\">还原与比较基期量</a><a data-toc-link href=\"#practice/s-9d6535a8dad068a9\">分项汇总与时段还原</a><a data-toc-link href=\"#practice/s-a28704d6c4e47be4\">按阈值筛选计数</a><a data-toc-link href=\"#practice/s-6cfd92b2f027f1a1\">数据与图表匹配</a><a data-toc-link href=\"#practice/s-9fc2e5daf6bbb9d8\">按增量或增速推算达标时间</a><a data-toc-link href=\"#practice/s-bc3e3cd5b0647c96\">基期与两期比重</a><a data-toc-link href=\"#practice/s-f727adc9d8af6663\">年均与跨期增长率</a><a data-toc-link href=\"#practice/s-d495edd4c80a44de\">核对指标所需数据与统计范围</a><a data-toc-link href=\"#practice/s-ddad42966dfee84f\">指标排序与定位</a><a data-toc-link href=\"#practice/s-a889bfbec9cac071\">分项与总体增长率</a><a data-toc-link href=\"#practice/s-3a4006f35d6c4142\">集合重叠与余量界限</a><a data-toc-link href=\"#practice/s-5e5c8fdd21d132b3\">增长倍数与期末量</a><a data-toc-link href=\"#practice/s-747f2e4430a1cd1a\">比较指标差额</a><a data-toc-link href=\"#practice/s-a227494d12288056\">增速的百分点差</a><a data-toc-link href=\"#practice/s-c0d36320cd06d980\">增长贡献率</a></div></details>","packs":{"国考 2023 地市级 行测#46":"308e5d78b64def13f06875f6","江苏 2024 A类 行测#23":"308e5d78b64def13f06875f6","国考 2023 行政执法 行测#42":"9c3e04a1c5fbb6927e913a80","国考 2023 行政执法 行测#53":"9c3e04a1c5fbb6927e913a80"},"questions":{"国考 2023 地市级 行测#46":{"paper":"国考 2023 地市级 行测","n":46,"mod":"言语理解与表达","src":["64bc3a15d27a04e94940.pdf",7],"asrc":["f3ab652d8e31c5bbdabc.pdf",15]},"江苏 2024 A类 行测#23":{"paper":"江苏 2024 A类 行测","n":23,"mod":"言语理解与表达","src":["f8fec75f67d6d1ba5759.pdf",4],"asrc":["0126a1c8aceee632ea2b.pdf",8]},"国考 2023 行政执法 行测#42":{"paper":"国考 2023 行政执法 行测","n":42,"mod":"言语理解与表达","src":["857378cf496f27296500.pdf",6],"asrc":["d23139fe5a0fb3115135.pdf",14]},"国考 2023 行政执法 行测#53":{"paper":"国考 2023 行政执法 行测","n":53,"mod":"言语理解与表达","src":["857378cf496f27296500.pdf",9],"asrc":["d23139fe5a0fb3115135.pdf",17]}},"first":{"qs":{"国考 2023 地市级 行测#46":{"paper":"国考 2023 地市级 行测","n":46,"mod":"言语理解与表达","src":["64bc3a15d27a04e94940.pdf",7],"asrc":["f3ab652d8e31c5bbdabc.pdf",15],"m":[],"task":"根据保护办法迟迟未出台及后续研究和立法进展，推断作者可能赞同的观点。","current_affairs":{"state":"否","event":null,"year":null,"basis":"立法时间和进展由题干提供，作者立场可依文意推断。"},"links":[{"id":"s-gist","label":"推断作者观点","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"时隔三十余年，保护办法仍未出台。","why":"转折突出保护办法长期缺位，后文的学界讨论和立法受阻共同指向作者对这一缺位的关切。","origin":"逐题标记","originalId":"s-6cbe71bb96acbbfe"},{"id":"s-300f89e88263b685","label":"通过转折定位文段重心","catalog_id":"ddd96a3c875dfde1","type":null,"role":"原有题组","field":"group","quote":"读出转折后的讨论重点","why":"原训练目录收录于该题组。","origin":"技能点库"}],"stem":"我国在改革开放后逐渐认识到保护民间文学艺术作品的重要性，并在1990年著作权法规定保护办法另行规定。但\n时隔三十余年，保护办法仍未出台。尽管如此，在著作权法颁布后，学界就民间文学艺术作品法律保护展开研究讨\n论，提出多种保护方案，涉及权利客体、权利主体、权利内容、保护期限、权利限制等方面的问题。当然，也有个\n\n别学者反对用著作权法保护民间文学艺术作品，主张通过公法加以保护。与此同时，国家版权局也加快推进相关立\n法，但因质疑声音过大而夭折。\n作者可能赞同下列哪一观点？","options":["通过公法保护民间文学艺术作品是最可行的路径","围绕民间文学艺术作品法律保护的争议流于表面","国家版权局应就民间文学保护倾听多方面意见","民间文学艺术作品法律保护缺位状态亟须改变"],"answer":"D","analysis":"46. 正确答案：D\n解析：\n文段开篇指出我国认识到保护民间文学艺术作品的重要性，并在著作权法中规定对保护办法另行规定。随后通\n过“但”表转折，指出当前民间文学艺术作品的保护办法仍然没有出台。接着介绍著作权法颁布后，学界针对民间文学\n艺术作品法律保护曾提出多种保护方案，涉及多方面问题，并指出个别学者主张通过公法加以保护。最后通过“与此\n同时”表示并列，介绍国家版权局也加快推进相关立法，但因受到强烈质疑而夭折。整个文段都是围绕民间文学艺术\n作品法律保护缺失这一问题展开论述，意在强调当前亟须出台民间文学艺术作品的保护法，对应D项。\nA项，“通过公法保护民间文学艺术作品”仅为个别学者的观点，“最可行”表述过于绝对，排除；\nB项，文段指出学界就民间文学艺术作品法律保护展开的研究讨论涉及多方面问题，“流于表面”与文意相悖，排除；\nC项，仅对应“与此同时”之后的内容，表述片面，且文段指出国家版权局的立法工作因受到质疑而夭折，并非没有“倾\n听多方面意见”，排除。\n故正确答案为D。\n【文段出处】《中国特色民间文学艺术作品著作权保护理论的构建》\n【考点】\n中心理解题-关联词-转折,中心理解题-特殊问法-其他","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false},"江苏 2024 A类 行测#23":{"paper":"江苏 2024 A类 行测","n":23,"mod":"言语理解与表达","src":["f8fec75f67d6d1ba5759.pdf",4],"asrc":["0126a1c8aceee632ea2b.pdf",8],"m":[],"task":"根据转折句和随后的辨析，概括作者对当前跨学科研究认识的判断。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作者的判断及其说明都在文段内。"},"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"不过，我们可能低估了跨学科的难度。","why":"由“不过”定位作者的判断，并识别后文关于术语混用和多学科简单组合的辨析对该判断的说明作用。","origin":"逐题标记"},{"id":"s-300f89e88263b685","label":"通过转折定位文段重心","catalog_id":"ddd96a3c875dfde1","type":null,"role":"原有题组","field":"group","quote":"读出转折后的讨论重点","why":"原训练目录收录于该题组。","origin":"技能点库"}],"stem":"有人认为，知识本来是一个整体，学科拆散了它，跨学科便是将分散的知识重新整合，是对过度专业化的反对。\n不过，我们可能低估了跨学科的难度。使用几个不同学科的概念，或与其他学科的研究者合写一篇论文，把那些本\n无多少新意的内容转换成混杂多个学科术语的表述，并不是真正的跨学科研究。“跨学科”不同于“多学科”，后者指两\n个或两个以上学科的简单组合，例如由不同学科教师团队讲授的特定课程。在这种情况下，学科之间仅是一种相邻\n关系，并没有真正结合。\n这段文字意在说明：","options":["跨学科需要对知识重新整合","跨学科需不同学科的交叉融合","多学科和跨学科存在着差异","当下对跨学科的认识存在误区"],"answer":"D","analysis":"23. 正确答案：D\n解析：\n文段开篇提出某人的观点，即知识本来是一个整体，学科拆散了它，接着引出“跨学科”的话题，指出跨学科便是将分\n散的知识重新整合，随后通过转折词“不过”强调我们可能低估了跨学科的难度，然后通过使用不同学科的概念和与其\n他学科的研究者合写一篇论文都不是真正的跨学科研究、“跨学科”不同于“多学科”等内容进行具体解释说明。故文段\n意在强调我们当下对跨学科认识不足，低估了跨学科的难度，对应D项。\nA项：“对知识重新整合”属于转折词“不过”之前的内容，非重点，排除。\nB项：“需不同学科的交叉融合”文段未提及，无中生有，排除。\nC项：“存在着差异”属于后文解释说明的内容，非重点，排除。\n故正确答案为D。\n【文段出处】《文科人“跨学科”，一种修辞，一场苦修》\n【考点】\n中心理解题-关联词-转折,分述句特征-引入铺垫,分述句特征-其他","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false}},"materialFiles":{},"terms":{"s-gist":{"id":"s-gist","mode":"s","type":"言语理解与表达","title":"主旨与作者意图","qs":[],"count":131},"s-300f89e88263b685":{"id":"s-300f89e88263b685","mode":"s","type":"言语理解与表达","title":"通过转折定位文段重心","qs":[],"count":4}},"questions":{}},"firstMaterials":[],"node":{"id":"s-300f89e88263b685","mode":"s","title":"通过转折定位文段重心","type":"言语理解与表达","domain":"言语理解与表达方法","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2023 地市级 行测#46","国考 2023 行政执法 行测#42","国考 2023 行政执法 行测#53","江苏 2024 A类 行测#23"],"current":false,"candidates":false,"legacySkill":"ddd96a3c875dfde1","trainingGroups":[{"name":"读出转折后的讨论重点","ids":["国考 2023 地市级 行测#46","江苏 2024 A类 行测#23"]},{"name":"顺着转折找到主张或对策","ids":["国考 2023 行政执法 行测#42","国考 2023 行政执法 行测#53"]}],"basisGroup":"","authority":null,"sourceOnly":false,"subject":"行测","directorySummary":"标出转折词，分别概括前后两层意思。再看后文如何论证、解释或提出对策，选择能覆盖作者主张的选项。","sources":[{"id":"ddd96a3c875dfde1","label":"通过转折定位文段重心","topic":"言语理解与表达方法","category":"非时政","text":"标出转折词，分别概括前后两层意思。再看后文如何论证、解释或提出对策，选择能覆盖作者主张的选项。","source":{"doc":"f3ab652d8e31c5bbdabc","first":15,"last":15,"file":"f3ab652d8e31c5bbdabc.pdf","page":15},"basis":"据题目与解析整理"}],"publishedSets":[{"name":"读出转折后的讨论重点","ids":["国考 2023 地市级 行测#46","江苏 2024 A类 行测#23"],"units":[["国考 2023 地市级 行测#46"],["江苏 2024 A类 行测#23"]]},{"name":"顺着转折找到主张或对策","ids":["国考 2023 行政执法 行测#42","国考 2023 行政执法 行测#53"],"units":[["国考 2023 行政执法 行测#42"],["国考 2023 行政执法 行测#53"]]}]}};
